ga9b(){return"\u0625\u0631\u0633\u0627\u0644 \u0631\u0627\u0628\u0637 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0639\u064a\u064a\u0646"},
ga9c(){return"\u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0646\u0627\u0643 \u062d\u0633\u0627\u0628 \u0645\u0631\u062a\u0628\u0637 \u0628\u0647\u0630\u0627 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u060c \u0641\u0633\u064a\u0635\u0644\u0643 \u0631\u0627\u0628\u0637 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0639\u064a\u064a\u0646 \u0642\u0631\u064a\u0628\u064b\u0627."},
ga9a(){return"\u0623\u062f\u062e\u0644 \u0628\u0631\u064a\u062f\u0643 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a"},
gaiP(){return"\u062a\u0639\u064a\u064a\u0646 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062c\u062f\u064a\u062f\u0629"},
gaiN(){return"\u0627\u062e\u062a\u0631 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062c\u062f\u064a\u062f\u0629 \u0644\u062d\u0633\u0627\u0628\u0643."},
gaiL(){return"\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629"},
gaiJ(){return"\u062a\u0623\u0643\u064a\u062f \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629"},
gaiM(){return"\u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631"},
gaiO(){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631. \u064a\u0631\u062c\u0649 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0628\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629."},
gajB(){return"\u0642\u0648\u0633 \u0643\u0627\u0645\u0644 / \u063a\u064a\u0631 \u0645\u062d\u062f\u062f"},
gajx(){return"\u062a\u0645 \u062a\u0639\u064a\u064a\u0646\u0647 \u0628\u0627\u0644\u0641\u0639\u0644 \u0644\u0646\u0648\u0639 \u0622\u062e\u0631 \u0636\u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0637\u0644\u0628"},
gajC(){return"\u062a\u062d\u062f\u064a\u062f \u0623\u0648 \u0625\u0644\u063a\u0627\u0621 \u062a\u062d\u062f\u064a\u062f \u0647\u0630\u0627 \u0627\u0644\u0631\u0628\u0639 \u0628\u0627\u0644\u0643\u0627\u0645\u0644"},
gajz(){return"\u0631\u0628\u0637 \u0627\u0644\u0633\u0646\u0651\u064a\u0646 (\u062c\u0633\u0631)"},
gajA(){return"\u062c\u0633\u0631. \u0627\u0636\u063a\u0637 \u0644\u0644\u0641\u0635\u0644"},
gajy(){return"\u0627\u0636\u063a\u0637 \u0627\u0644\u062f\u0627\u0626\u0631\u0629 \u0628\u064a\u0646 \u0633\u0646\u0651\u064a\u0646 \u0644\u0631\u0628\u0637\u0647\u0645\u0627 \u0643\u062c\u0633\u0631\u060c \u0648\u0627\u062a\u0631\u0643\u0647\u0627 \u0641\u0627\u0631\u063a\u0629 \u0625\u0630\u0627 \u0643\u0627\u0646\u0627 \u0645\u0646\u0641\u0635\u0644\u064a\u0646."},
gQW(){return"\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a"},
gQN(){return"\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0641\u0631\u0639 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u062a\u0641\u0636\u064a\u0644\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629."},
gOx(){return"\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0641\u0631\u0639"},
gPW(){return"\u0627\u0644\u062f\u0641\u0639 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a"},
gPX(){return"\u0627\u0633\u0645\u062d \u0644\u0644\u0639\u064a\u0627\u062f\u0627\u062a \u0628\u0627\u0644\u062f\u0641\u0639 \u0644\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0628\u0631 \u0645\u0632\u0648\u062f \u062f\u0641\u0639. \u0643\u0644 \u0645\u0632\u0648\u062f \u064a\u062d\u062a\u0627\u062c \u062d\u0633\u0627\u0628\u0647 \u0627\u0644\u062a\u062c\u0627\u0631\u064a \u0627\u0644\u062e\u0627\u0635\u060c \u064a\u062a\u0645 \u0625\u0639\u062f\u0627\u062f\u0647 \u0628\u0634\u0643\u0644 \u0645\u0646\u0641\u0635\u0644 \u0645\u0639 \u0630\u0644\u0643 \u0627\u0644\u0645\u0632\u0648\u062f."},
gPa(){return"\u0645\u0641\u0639\u0651\u0644"},
gPd(){return"\u063a\u064a\u0631 \u0645\u0647\u064a\u0623"},
gP6(){return"\u0642\u0631\u064a\u0628\u0627\u064b"},
gP7(){return"\u0625\u0639\u062f\u0627\u062f"},
P9(a){return"\u0625\u0639\u062f\u0627\u062f "+a},
gPb(){return"\u0642\u0628\u0648\u0644 \u0627\u0644\u062f\u0641\u0639\u0627\u062a \u0639\u0628\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u0632\u0648\u062f"},
gP8(){return"\u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0644\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629"},
gPf(){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0645\u0632\u0648\u062f \u0627\u0644\u062f\u0641\u0639."},
Pe(a){return"\u0641\u0634\u0644 \u0627\u0644\u062d\u0641\u0638: "+a},
gPc(){return"\u0627\u0645\u0644\u0623 \u0627\u0644\u062d\u0642\u0648\u0644 \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u062c\u0645\u064a\u0639\u0647\u0627\u060c \u0623\u0648 \u0627\u062a\u0631\u0643\u0647\u0627 \u0641\u0627\u0631\u063a\u0629 \u062c\u0645\u064a\u0639\u0627\u064b \u0644\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629."},
gR4(){return"\u0631\u0642\u0645 \u0627\u0644\u0645\u062d\u0641\u0638\u0629 (msisdn)"},
