gR5(){return"\u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0633\u0631\u064a"},
gR6(){return"\u0648\u0636\u0639 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 (\u062a\u062c\u0631\u064a\u0628\u064a)"},
gQa(){return"\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645"},
gQ8(){return"\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631"},
gQ9(){return"\u0645\u0639\u0631\u0651\u0641 \u0627\u0644\u0637\u0631\u0641\u064a\u0629"},
gP1(){return"\u0645\u0639\u0631\u0651\u0641 \u0627\u0644\u0639\u0645\u064a\u0644"},
gP2(){return"\u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0633\u0631\u064a \u0644\u0644\u0639\u0645\u064a\u0644"},
gPB(){return"\u0645\u0641\u062a\u0627\u062d API"},
gPC(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a"},
gPV(){return"\u0644\u0627 \u064a\u062a\u0648\u0641\u0631 \u0628\u0639\u062f \u0645\u0632\u0648\u0651\u062f \u062f\u0641\u0639 \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0644\u0628\u0644\u062f\u0643. \u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0625\u0636\u0627\u0641\u0629 \u0648\u0627\u062d\u062f."},
gP5(){return"\u0631\u0627\u0628\u0637 \u0627\u0644\u0625\u0646\u062a\u0627\u062c (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gP4(){return"\u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a. \u0647\u0630\u0627 \u0627\u0644\u0645\u0632\u0648\u062f \u0644\u0627 \u064a\u0646\u0634\u0631 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0625\u0646\u062a\u0627\u062c \u0627\u0644\u062e\u0627\u0635 \u0628\u0647 \u0639\u0644\u0646\u0627\u064b \u2014 \u0627\u062d\u0635\u0644 \u0639\u0644\u064a\u0647 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0646\u0647 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0639\u0644\u0649 \u062d\u0633\u0627\u0628\u0643."},
gQ_(){return"\u062a\u0641\u0636\u064a\u0644\u0627\u062a\u064a"},
