ga21(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u060c \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u0627\u062f\u062f\u06d5\u06a9\u0627\u0646 \u2014 \u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u0648\u06ce\u0646\u06ce\u06a9 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u0646."},
ga20(){return"\u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646"},
gHC(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga0W(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga0a(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u062f\u0646"},
ga0O(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc"},
ga1P(){return"\u06af\u06d5\u0695\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5"},
ga0e(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u0627\u0648"},
ga0d(){return"\u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5 \u0626\u06d5\u0631\u0634\u06cc\u0641 \u0628\u06a9\u0631\u06ce\u062a\u061f"},
a0c(a){return"\xab"+a+"\xbb \u0644\u06d5 \u0647\u06ce\u06b5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0648 \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06a9\u06d5 \u0644\u0627\u062f\u06d5\u0628\u0631\u062f\u0631\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06d5 \u06a9\u06c6\u0646\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u06ce\u0698\u0648\u0648 \u0646\u0627\u0648\u06d5\u06a9\u06d5 \u062f\u06d5\u0647\u06ce\u06b5\u0646\u06d5\u0648\u06d5. \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u0628\u06cc\u06af\u06d5\u0695\u06ce\u0646\u06cc\u062a\u06d5\u0648\u06d5."},
ga0b(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u062f\u0646"},
ga0Q(){return"\u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5 \u0628\u06c6 \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u0628\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5\u061f"},
a0P(a){return"\xab"+a+"\xbb \u0628\u06c6 \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5. \u0626\u06d5\u0645\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u06a9\u0627\u0631\u062f\u06d5\u06a9\u0627\u062a \u0626\u06d5\u06af\u06d5\u0631 \u0647\u06cc\u0686 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0628\u06d5\u06a9\u0627\u0631\u06cc \u0646\u06d5\u0647\u06ce\u0646\u0627\u0628\u06ce\u062a."},
gHK(){return"\u0642\u06c6\u0646\u0627\u063a \u0644\u0627\u0628\u0631\u062f\u0631\u0627."},
ga1Z(){return"\u0642\u06c6\u0646\u0627\u063a \u06af\u06d5\u0695\u06ce\u0646\u062f\u0631\u0627\u06cc\u06d5\u0648\u06d5."},
ga1_(){return" \xb7 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646"},
ga0Y(){return" \xb7 \u06a9\u06c6\u062a\u0627\u06cc\u06cc"},
ga0Z(){return"\u0626\u06d5\u0645\u06d5 \u0642\u06c6\u0646\u0627\u063a\u06cc \u06a9\u06c6\u062a\u0627\u06cc\u06cc\u06d5: \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0628\u06af\u0648\u0627\u0632\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u0628\u06c6 \u0626\u06ce\u0631\u06d5 \u0648\u06d5\u06a9 \u0646\u06ce\u0631\u062f\u0631\u0627\u0648 \u0626\u06d5\u0698\u0645\u0627\u0631 \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0648 \u0686\u06cc\u062a\u0631 \u0686\u0627\u0644\u0627\u06a9 \u0646\u06cc\u06cc\u06d5. \u0648\u06d5\u06a9 \u0642\u06c6\u0646\u0627\u063a\u06cc \u06af\u06d5\u06cc\u0627\u0646\u062f\u0646 \u0628\u06cc\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5. \u0628\u06c6 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0647\u06d5\u0646\u06af\u0627\u0648\u06ce\u06a9\u06cc \u062a\u0631\u060c \u0642\u06c6\u0646\u0627\u063a\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5 \u0644\u06d5 \u062c\u06cc\u0627\u062a\u06cc \u06af\u06c6\u0695\u06cc\u0646\u06cc \u0646\u0627\u0648\u06cc \u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5."},
ga1A(){return"\u0628\u06c6 \u067e\u06ce\u0634\u06d5\u0648\u06d5 \u0628\u06af\u0648\u0627\u0632\u06d5\u0631\u06d5\u0648\u06d5"},
ga1z(){return"\u0628\u06c6 \u062f\u0648\u0627\u0648\u06d5 \u0628\u06af\u0648\u0627\u0632\u06d5\u0631\u06d5\u0648\u06d5"},
gHI(){return"\u0628\u06cc\u0628\u06d5 \u0633\u06d5\u0631\u06d5\u0648\u06d5 (\u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06d5\u06cc\u0633 \u067e\u06ce\u0634\u062a\u0631 \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u06ce\u062a)"},
gHH(){return"\u0628\u06cc\u0628\u06d5 \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5"},
