ga1T(){return"\u0695\u06d5\u0646\u06af (\u0647\u06ce\u06a9\u0633\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 FFB8763F)"},
ga0s(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
gHw(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
ga0R(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
ga0j(){return"\u0646\u0627\u0648"},
ga0m(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u0695\u06c6\u0698\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0628\u06c6 \u0628\u06d5\u0631\u0648\u0627\u0631\u06cc \u06af\u06d5\u06cc\u0634\u062a\u0646"},
ga0l(){return"\u0628\u06c6 \u067e\u06ce\u0634\u0646\u06cc\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0628\u06d5\u0631\u0648\u0627\u0631\u06cc \u06af\u06d5\u06cc\u0634\u062a\u0646 \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u0644\u06d5\u0645 \u062c\u06c6\u0631\u06d5 \u062f\u0631\u0648\u0633\u062a \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0628\u06d5\u06a9\u0627\u0631\u062f\u06ce\u062a \u2014 \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u06c6 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0628\u06af\u06c6\u0695\u062f\u0631\u06ce\u062a."},
ga0r(){return"\u0695\u06d5\u0646\u06af\u06cc \u0628\u06d5\u06a9\u0627\u0631\u062f\u06d5\u0647\u06ce\u0646\u06ce\u062a"},
ga0q(){return"\u0644\u06cc\u0633\u062a\u06cc \u062f\u06cc\u0632\u0627\u06cc\u0646\u06cc \u0645\u0627\u0631\u062c\u0646/\u06a9\u06c6\u0646\u062a\u0627\u06a9\u062a/\u067e\u06c6\u0646\u062a\u06cc\u06a9 + \u062a\u06d5\u0645\u06d5\u0646/\u0695\u06d5\u06af\u06d5\u0632 \u0644\u06d5\u0633\u06d5\u0631 \u0644\u06d5\u06cc\u0628\u06b5 \u0686\u0627\u067e \u0628\u06a9\u06d5"},
ga0p(){return"\u0628\u06c6 \u06a9\u0627\u0631\u06cc \u062a\u0627\u062c/\u067e\u0631\u062f \u2014 \u0628\u06c6\u06a9\u0633\u06cc \u0628\u06d5\u062a\u0627\u06b5\u06cc \u062f\u06cc\u0632\u0627\u06cc\u0646\u06cc \u0645\u0627\u0631\u062c\u0646/\u06a9\u06c6\u0646\u062a\u0627\u06a9\u062a/\u067e\u06c6\u0646\u062a\u06cc\u06a9 \u0648 \u062a\u06d5\u0645\u06d5\u0646/\u0695\u06d5\u06af\u06d5\u0632 \u0632\u06cc\u0627\u062f \u062f\u06d5\u06a9\u0627\u062a \u0628\u06c6 \u0644\u06d5\u06cc\u0628\u06b5\u06cc \u0686\u0627\u067e\u06a9\u0631\u0627\u0648 \u062a\u0627\u06a9\u0648 \u062a\u06d5\u06a9\u0646\u06cc\u0633\u06cc\u0627\u0646 \u0628\u06d5 \u062f\u06d5\u0633\u062a \u0647\u06d5\u06b5\u06cc\u0628\u0698\u06ce\u0631\u06ce\u062a. \u0626\u06d5\u0645 \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06d5 \u062f\u0627\u0628\u062e\u06d5 \u062f\u0648\u0627\u06cc \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u0627\u0646 \u0648\u0631\u062f\u06d5\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u062a \u0648\u06d5\u06a9 \u062a\u0627\u06cc\u0628\u06d5\u062a\u0645\u06d5\u0646\u062f\u06cc \u0695\u0627\u0633\u062a\u06d5\u0642\u06cc\u0646\u06d5 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f \u0628\u06c6 \u0626\u06d5\u0645 \u062c\u06c6\u0631\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5 (\u062a\u0627\u06a9\u0648 \u0644\u06d5\u06cc\u0628\u06b5\u06d5\u06a9\u06d5 \u0628\u06d5\u0647\u0627\u06cc \u0695\u0627\u0633\u062a\u06d5\u0642\u06cc\u0646\u06d5 \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u0627\u062a \u0646\u06d5\u06a9 \u0628\u06c6\u06a9\u0633\u06ce\u06a9\u06cc \u0628\u06d5\u062a\u0627\u06b5)."},
ga0o(){return"\u0628\u0627\u0632\u0646\u06d5\u06cc \u067e\u0631\u062f \u0644\u06d5\u0633\u06d5\u0631 \u0646\u06d5\u062e\u0634\u06d5\u06cc \u062f\u062f\u0627\u0646"},
ga0n(){return"\u0628\u06c6 \u06a9\u0627\u0631\u06cc \u062a\u0627\u062c \u0648 \u067e\u0631\u062f \u0648 \u0626\u06cc\u0645\u067e\u0644\u0627\u0646\u062a: \u0628\u0627\u0632\u0646\u06d5\u06cc\u06d5\u06a9 \u0644\u06d5 \u0646\u06ce\u0648\u0627\u0646 \u062f\u0648\u0648 \u062f\u062f\u0627\u0646\u06cc \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u062f\u0631\u0627\u0648 \u0648\u06d5\u06a9 \u067e\u0631\u062f \u0628\u06d5\u06cc\u06d5\u06a9\u06cc\u0627\u0646 \u062f\u06d5\u0628\u06d5\u0633\u062a\u06ce\u062a\u060c \u0648 \u067e\u0631\u062f\u06d5\u06a9\u06d5 \u0644\u06d5\u0633\u06d5\u0631 \u0644\u06d5\u06cc\u0628\u06b5 \u0686\u0627\u067e \u062f\u06d5\u06a9\u0631\u06ce\u062a. \u0628\u06c6 \u0626\u06d5\u0648 \u062c\u06c6\u0631\u0627\u0646\u06d5\u06cc \u0647\u06d5\u0631\u06af\u06cc\u0632 \u067e\u0631\u062f\u06cc\u0627\u0646 \u0646\u06cc\u06cc\u06d5 (\u06a4\u06cc\u0646\u06cc\u0631\u060c \u062f\u062f\u0627\u0646\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f\u060c \u0626\u0627\u0645\u06ce\u0631\u06d5\u06a9\u0627\u0646) \u062f\u0627\u06cc\u0628\u062e\u06d5."},
ga1V(){return"\u0642\u06c6\u0646\u0627\u063a\u06cc \u062c\u06cc\u0627\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646"},
ga1U(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06cc \u0686\u06d5\u0646\u062f \u062c\u06c6\u0631\u06cc \u0633\u06a9\u0627\u0646 \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0628\u06c6 \u0686\u0648\u0648\u0646\u06d5 \u0646\u0627\u0648 (\u06cc\u0627\u0646 \u062f\u06d5\u0631\u0686\u0648\u0648\u0646 \u0644\u06d5) \u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5\u060c \u062a\u06d5\u0646\u0647\u0627 \u0626\u06d5\u0648 \u06cc\u06d5\u06a9\u0627\u0646\u06d5 \u067e\u06ce\u0634\u062f\u06d5\u06a9\u06d5\u0648\u0646 \u06a9\u06d5 \u0645\u0627\u062f\u062f\u06d5\u06a9\u06d5\u06cc\u0627\u0646 \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u0627\u0645\u06ce\u0631\u06cc \u0626\u06d5\u0648 \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u06d5\u0631\u06d5\u06cc \u0633\u06a9\u0627\u0646\u06cc \u06a9\u0631\u062f \u062f\u06d5\u06af\u0648\u0646\u062c\u06ce\u062a. \u0626\u06d5\u0645\u06d5 \u0644\u06d5\u0633\u06d5\u0631 \u0642\u06c6\u0646\u0627\u063a\u06cc \u06a9\u0628\u0633/\u062e\u0631\u0627\u0637\u06d5 \u062f\u0627\u0628\u0646\u06ce."},
ga1b(){return"\u0695\u06ce\u0695\u06d5\u0648\u06cc \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646"},
ga1a(){return"\u0644\u06d5 \u0642\u06c6\u0646\u0627\u063a\u06cc \u062c\u06cc\u0627\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u060c \u062a\u06d5\u0646\u0647\u0627 \u0633\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u06d5\u0631\u06d5 \u06cc\u06d5\u06a9\u0627\u0646\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u0645\u0627\u062f\u062f\u06d5\u06cc\u06d5 \u067e\u06ce\u0634\u062f\u06d5\u062e\u0627\u062a \u0644\u06d5 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0686\u06d5\u0646\u062f \u062c\u06c6\u0631\u06cc."},
ga1c(){return"\u0628\u06ce \u0695\u06ce\u0695\u06d5\u0648 (\u0644\u06d5\u06af\u06d5\u06b5 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5 \u062f\u06d5\u062c\u0648\u06b5\u06ce\u062a)"},
