g=A.cv('<!doctype html>\n<html lang="__LANG__" dir="__DIR__">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>__TITLE__</title>\n<style>\n:root{--bg:#f4f5fa;--card:#fff;--ink:#1d2140;--soft:#5b6080;--faint:#8b90ad;--line:#e4e6f0;--accent:#4f46e5;--accent-ink:#fff;--tint:#eef0ff;--zebra:#fafbff}\n@media (prefers-color-scheme:dark){:root{--bg:#12142a;--card:#1b1e38;--ink:#eceefb;--soft:#a3a8cf;--faint:#7c82ad;--line:#2b2f52;--accent:#8b85ff;--accent-ink:#12142a;--tint:#262a4c;--zebra:#1f2240}}\n*{box-sizing:border-box}\nhtml,body{height:100%}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:system-ui,"Segoe UI",Tahoma,Arial,sans-serif;font-size:14px;line-height:1.4}\na{color:var(--accent);text-decoration:none}\na:hover{text-decoration:underline}\n.app{display:flex;min-height:100%}\naside{width:250px;flex:none;background:var(--card);border-inline-end:1px solid var(--line);padding:18px 12px;position:sticky;top:0;height:100vh;overflow:auto}\n.brand{display:flex;gap:10px;align-items:center;padding:0 6px 14px;border-bottom:1px solid var(--line);margin-bottom:10px}\n.logo{width:38px;height:38px;border-radius:10px;background:var(--accent);color:var(--accent-ink);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:18px;flex:none}\n.brand b{display:block;font-size:15px;line-height:1.2;word-break:break-word}\n.brand small{color:var(--faint);font-size:11.5px}\n.grp{font-size:11px;letter-spacing:.04em;text-transform:uppercase;color:var(--faint);margin:14px 8px 4px}\n.nav{display:flex;justify-content:space-between;gap:8px;width:100%;border:0;background:none;color:var(--ink);padding:7px 10px;border-radius:8px;cursor:pointer;font:inherit;text-align:start}\n.nav:hover{background:var(--tint)}\n.nav.on{background:var(--accent);color:var(--accent-ink)}\n.nav span:last-child{opacity:.65;font-variant-numeric:tabular-nums}\nmain{flex:1;min-width:0;padding:22px 26px 48px}\nh1{margin:0 0 2px;font-size:22px}\n.sub{color:var(--soft);font-size:13px;margin-bottom:16px}\n.bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:0 0 12px}\n.bar .grow{flex:1}\ninput[type=search]{width:100%;max-width:380px;padding:9px 12px;border:1px solid var(--line);border-radius:9px;background:var(--card);color:var(--ink);font:inherit}\n.btn{border:1px solid var(--line);background:var(--card);color:var(--ink);padding:8px 14px;border-radius:9px;cursor:pointer;font:inherit}\n.btn:hover{background:var(--tint)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}\ndetails.cols{position:relative}\ndetails.cols summary{list-style:none}\ndetails.cols summary::-webkit-details-marker{display:none}\n.colmenu{position:absolute;z-index:5;inset-inline-start:0;top:110%;width:260px;max-height:360px;overflow:auto;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:8px;box-shadow:0 8px 24px rgba(0,0,0,.15)}\n.colmenu label{display:flex;gap:8px;padding:4px 6px;border-radius:6px;cursor:pointer}\n.colmenu label:hover{background:var(--tint)}\n.count{color:var(--soft);font-size:13px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:12px}\n.wrap{overflow:auto;max-height:calc(100vh - 190px)}\ntable{border-collapse:collapse;width:100%}\nth,td{padding:8px 12px;border-bottom:1px solid var(--line);text-align:start;vertical-align:top}\ntd{max-width:340px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\ntd:hover{white-space:normal;overflow:visible}\ntd.n,th.n{text-align:end;font-variant-numeric:tabular-nums}\nth{position:sticky;top:0;background:var(--tint);cursor:pointer;user-select:none;z-index:1;white-space:nowrap;font-weight:600}\ntbody tr:nth-child(even){background:var(--zebra)}\ntd a.f{display:inline-block;margin-inline-end:8px}\n.empty{padding:28px;color:var(--soft)}\ntd.d{white-space:nowrap}\na.f{display:inline-block;margin-inline-end:12px}\n#more{margin:14px 0}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:0 0 20px}\n.stat{padding:14px 16px;cursor:pointer}\n.stat:hover{border-color:var(--accent)}\n.stat b{display:block;font-size:26px;font-variant-numeric:tabular-nums}\n.stat span{color:var(--soft);font-size:13px}\n.sec{margin:22px 0 8px;font-size:15px;font-weight:700}\n.kv{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:0}\n.kv div{padding:10px 14px;border-bottom:1px solid var(--line)}\n.kv small{display:block;color:var(--faint);font-size:11.5px;margin-bottom:2px}\n.kv .big{grid-column:1/-1}\n.kv .big span{white-space:pre-wrap}\n.msg{padding:10px 14px;border-bottom:1px solid var(--line)}\n.msg small{color:var(--faint)}\n.pagehead{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:6px}\n.pagehead h1{flex:1;min-width:0}\n.phead{display:none}\n@media (max-width:820px){\n  .app{flex-direction:column}\n  aside{width:auto;height:auto;position:static;border-inline-end:0;border-bottom:1px solid var(--line)}\n  main{padding:16px}\n}\n@media print{\n  @page{size:A4 landscape;margin:10mm}\n  :root{--bg:#fff;--card:#fff;--ink:#000;--soft:#333;--faint:#555;--line:#bbb;--tint:#eee;--zebra:#fff;--accent:#000}\n  html,body{height:auto}\n  body{font-size:9pt;background:#fff}\n  aside,.bar,.noprint,#more,.btn{display:none!important}\n  .app{display:block}\n  main{padding:0}\n  .wrap{max-height:none;overflow:visible}\n  .card{border:0}\n  .phead{display:block;margin-bottom:6px}\n  .pagehead,.sub{display:none}\n  td.d{white-space:nowrap!important}\n  .phead b{font-size:13pt}\n  th,td{padding:3px 5px;white-space:normal!important;max-width:none;overflow:visible;font-size:8.5pt}\n  th{position:static}\n  thead{display:table-header-group}\n  tr{page-break-inside:avoid}\n  tbody tr:nth-child(even){background:#f4f4f4}\n  td a{color:#000}\n  .cards{display:none}\n  .sec{page-break-after:avoid}\n}\n</style>\n</head>\n<body>\n<div class="app">\n<aside>\n  <div class="brand"><div class="logo" id="logo"></div><div><b id="lab"></b><small id="date"></small></div></div>\n  <div id="nav"></div>\n</aside>\n<main id="view"></main>\n</div>\n<script id="d" type="application/json">__DATA__</script>\n<script>\n"use strict";\nconst D = JSON.parse(document.getElementById("d").textContent);\nconst L = D.L, PAGE = 300;\nconst $ = (id) => document.getElementById(id);\nconst tabs = D.tabs, byKey = {};\ntabs.forEach((t) => {\n  byKey[t.key] = t;\n  t.ix = {};\n  t.cols.forEach((c, i) => { t.ix[c] = i; });\n  t.vis = t.def.slice();\n  t.query = ""; t.sortCol = -1; t.sortAsc = true; t.shown = PAGE;\n});\nconst get = (t, r, c) => { const i = t.ix[c]; return i === undefined ? "" : r[i]; };\nconst fmtNum = new Intl.NumberFormat("en-US", {maximumFractionDigits: 4});\nfunction show(t, i, v) {\n  if (Array.isArray(v) || v === "" || !t.num[i]) return v;\n  const n = Number(v);\n  return isNaN(n) ? v : fmtNum.format(n);\n}\nfunction fold(s) {\n  return String(s).replace(/\u0130/g, "i").replace(/\u0131/g, "i").toLowerCase()\n    .normalize("NFD").replace(/[\u0300-\u036f\u064b-\u065f\u0640]/g, "")\n    .replace(/[\u0623\u0625\u0622]/g, "\u0627").replace(/[\u06cc\u0649]/g, "\u064a")\n    .replace(/\u06a9/g, "\u0643").replace(/\u06d5/g, "\u0647");\n}\nconst plain = (c) => Array.isArray(c) ? c.map((x) => x[0]).join(" ") : c;\nfunction el(tag, cls, text) {\n  const e = document.createElement(tag);\n  if (cls) e.className = cls;\n  if (text !== undefined) e.textContent = text;\n  return e;\n}\n\n// ---- lookups used for links and the detail pages ----\nconst cases = byKey.cases, doctors = byKey.doctors, clinics = byKey.clinics;\nconst clinicIdByName = {}, doctorIdByKey = {}, caseRowByNo = {};\nclinics.rows.forEach((r) => { const n = get(clinics, r, "name"); if (!(n in clinicIdByName)) clinicIdByName[n] = get(clinics, r, "id"); });\ndoctors.rows.forEach((r) => { doctorIdByKey[get(doctors, r, "name") + "\\u0001" + get(doctors, r, "clinic")] = get(doctors, r, "id"); });\ncases.rows.forEach((r) => { caseRowByNo[get(cases, r, "case_number")] = r; });\nfunction groupBy(key, col) {\n  const t = byKey[key], m = {};\n  t.rows.forEach((r) => { const k = get(t, r, col); (m[k] = m[k] || []).push(r); });\n  return m;\n}\nconst histByCase = groupBy("stage_history", "case_number");\nconst msgsByCase = groupBy("messages", "case_number");\nconst filesByCase = groupBy("files", "case_number");\nconst allocByCase = groupBy("payment_allocations", "case_number");\n\nfunction link(text, hash, cls) {\n  const a = el("a", cls, text);\n  a.href = "#" + hash;\n  return a;\n}\n\n// ---- table building ----\nfunction fill(td, t, r, c, i) {\n  const v = r[i];\n  if (Array.isArray(v)) {\n    v.forEach((l) => { const a = el("a", "f", l[0]); a.href = l[1]; a.target = "_blank"; a.rel = "noopener"; td.appendChild(a); });\n    return;\n  }\n  const text = show(t, i, v);\n  if (v !== "" && c === "case_number") td.appendChild(link(text, "case/" + encodeURIComponent(v)));\n  else if (v !== "" && c === "doctor" && t.key === "cases" && (get(t, r, "doctor") + "\\u0001" + get(t, r, "clinic")) in doctorIdByKey)\n    td.appendChild(link(text, "doctor/" + doctorIdByKey[get(t, r, "doctor") + "\\u0001" + get(t, r, "clinic")]));\n  else if (v !== "" && c === "clinic" && v in clinicIdByName) td.appendChild(link(text, "clinic/" + clinicIdByName[v]));\n  else if (c === "name" && t.key === "doctors") td.appendChild(link(text, "doctor/" + get(t, r, "id")));\n  else if (c === "name" && t.key === "clinics") td.appendChild(link(text, "clinic/" + get(t, r, "id")));\n  else if (/^[+\\d][\\d\\s().+-]*$/.test(String(text))) {\n    // Phone numbers, dates, invoice numbers: keep left-to-right inside an\n    // RTL page ("+964 770 123" must not read backwards).\n    const b = el("bdi", "", text); b.dir = "ltr"; td.appendChild(b);\n  } else td.textContent = text;\n}\n// "n" = right-aligned number, "d" = never wrap (dates, case / invoice numbers).\nfunction cellClass(t, c, i) {\n  if (t.num[i]) return "n";\n  return /date|_at$|number|^month$|^period_/.test(c) ? "d" : "";\n}\nfunction buildTable(t, rows, cols, opts) {\n  opts = opts || {};\n  const table = el("table");\n  const thead = el("thead"), tr = el("tr");\n  cols.forEach((c) => {\n    const i = t.ix[c], th = el("th", t.num[i] ? "n" : "", t.headers[i] + (opts.sort && i === t.sortCol ? (t.sortAsc ? " \u25b2" : " \u25bc") : ""));\n    if (opts.sort) th.onclick = () => { if (t.sortCol === i) t.sortAsc = !t.sortAsc; else { t.sortCol = i; t.sortAsc = true; } t.shown = PAGE; opts.sort(); };\n    tr.appendChild(th);\n  });\n  thead.appendChild(tr);\n  table.appendChild(thead);\n  const tbody = el("tbody");\n  rows.forEach((r) => {\n    const row = el("tr");\n    cols.forEach((c) => { const i = t.ix[c], td = el("td", cellClass(t, c, i)); fill(td, t, r, c, i); row.appendChild(td); });\n    tbody.appendChild(row);\n  });\n  table.appendChild(tbody);\n  return table;\n}\nfunction wrapTable(table) {\n  const card = el("div", "card"), w = el("div", "wrap");\n  w.appendChild(table); card.appendChild(w);\n  return card;\n}\n\n// ---- views ----\nconst view = $("view");\nlet printing = false, current = null;\nfunction clear() { view.textContent = ""; }\nfunction head(title, sub, actions) {\n  const h = el("div", "pagehead");\n  h.appendChild(el("h1", "", title));\n  (actions || []).forEach((a) => h.appendChild(a));\n  view.appendChild(h);\n  if (sub) view.appendChild(el("div", "sub", sub));\n  const ph = el("div", "phead");\n  ph.appendChild(el("b", "", D.lab + " \u2014 " + title));\n  ph.appendChild(el("div", "", D.note));\n  view.appendChild(ph);\n}\nfunction printBtn() {\n  const b = el("button", "btn primary noprint", L.print);\n  b.onclick = () => window.print();\n  return b;\n}\nfunction backBtn() {\n  const b = el("button", "btn noprint", "\u2190 " + L.back);\n  b.onclick = () => { if (history.length > 1) history.back(); else location.hash = ""; };\n  return b;\n}\nfunction setNav(key) {\n  [...document.querySelectorAll(".nav")].forEach((b) => b.classList.toggle("on", b.dataset.key === key));\n}\n\nfunction showHome() {\n  current = null; clear(); setNav("home");\n  head(D.lab, D.note, []);\n  const open = cases.rows.filter((r) => !get(cases, r, "shipped_at") && !get(cases, r, "cancelled_at")).length;\n  const stats = [[cases.rows.length, D.titles.cases, "t/cases"], [open, L.openCases, "t/cases"], [clinics.rows.length, D.titles.clinics, "t/clinics"],\n    [doctors.rows.length, D.titles.doctors, "t/doctors"], [byKey.payments.rows.length, D.titles.payments, "t/payments"]];\n  const cs = el("div", "cards");\n  stats.forEach((s) => {\n    const c = el("div", "card stat");\n    c.appendChild(el("b", "", fmtNum.format(s[0])));\n    c.appendChild(el("span", "", s[1]));\n    c.onclick = () => { location.hash = s[2]; };\n    cs.appendChild(c);\n  });\n  view.appendChild(cs);\n  view.appendChild(el("div", "sec", L.latest));\n  const last = cases.rows.slice(-10).reverse();\n  const cols = cases.cols.filter((c, i) => cases.def[i]);\n  view.appendChild(wrapTable(buildTable(cases, last, cols)));\n}\n\nfunction showTab(key) {\n  const t = byKey[key] || tabs[0];\n  current = t.key; clear(); setNav(t.key);\n  head(t.title, "", [printBtn()]);\n  const bar = el("div", "bar");\n  const q = el("input"); q.type = "search"; q.placeholder = D.search; q.value = t.query;\n  const grow = el("div", "grow"); grow.appendChild(q);\n  bar.appendChild(grow);\n  const det = el("details", "cols"), sum = el("summary", "btn", L.columns + " \u25be");\n  det.appendChild(sum);\n  const menu = el("div", "colmenu");\n  const reset = el("button", "btn", L.defaultCols);\n  reset.onclick = () => { t.vis = t.def.slice(); menu.querySelectorAll("input").forEach((c, i) => { c.checked = t.vis[i]; }); draw(); };\n  menu.appendChild(reset);\n  t.cols.forEach((c, i) => {\n    const lab = el("label"), cb = el("input"); cb.type = "checkbox"; cb.checked = t.vis[i];\n    cb.onchange = () => { t.vis[i] = cb.checked; draw(); };\n    lab.appendChild(cb); lab.appendChild(el("span", "", t.headers[i]));\n    menu.appendChild(lab);\n  });\n  det.appendChild(menu);\n  bar.appendChild(det);\n  const count = el("span", "count");\n  bar.appendChild(count);\n  view.appendChild(bar);\n  const holder = el("div");\n  view.appendChild(holder);\n  const more = el("button", "btn", L.showMore); more.id = "more";\n  view.appendChild(more);\n  more.onclick = () => { t.shown += PAGE; draw(); };\n  q.oninput = () => { t.query = q.value; t.shown = PAGE; draw(); };\n  function draw() {\n    const f = fold(t.query.trim());\n    if (!t.hay) t.hay = t.rows.map((r) => fold(r.map(plain).join(" ")));\n    let idx = [];\n    for (let i = 0; i < t.rows.length; i++) if (!f || t.hay[i].includes(f)) idx.push(i);\n    if (t.sortCol >= 0) {\n      idx.sort((a, b) => {\n        const x = plain(t.rows[a][t.sortCol]), y = plain(t.rows[b][t.sortCol]);\n        const r = t.num[t.sortCol] ? (Number(x) || 0) - (Number(y) || 0) : String(x).localeCompare(String(y), undefined, {numeric: true});\n        return t.sortAsc ? r : -r;\n      });\n    }\n    const limit = printing ? idx.length : t.shown;\n    const cols = t.cols.filter((c, i) => t.vis[i]);\n    holder.textContent = "";\n    if (idx.length === 0) holder.appendChild(el("div", "card empty", D.empty));\n    else holder.appendChild(wrapTable(buildTable(t, idx.slice(0, limit).map((i) => t.rows[i]), cols, {sort: draw})));\n    count.textContent = D.showing.replace("-1", Math.min(limit, idx.length)).replace("-2", idx.length);\n    more.hidden = limit >= idx.length;\n  }\n  t.redraw = draw;\n  draw();\n}\n\nfunction kv(t, r, hide) {\n  const box = el("div", "card kv");\n  t.cols.forEach((c, i) => {\n    const v = r[i];\n    if (v === "" || (Array.isArray(v) && !v.length) || (hide && hide.indexOf(c) >= 0)) return;\n    const d = el("div", c === "note" || c === "message" ? "big" : "");\n    d.appendChild(el("small", "", t.headers[i]));\n    const s = el("span");\n    fill(s, t, r, c, i);\n    d.appendChild(s);\n    box.appendChild(d);\n  });\n  return box;\n}\nfunction section(title, node) { view.appendChild(el("div", "sec", title)); view.appendChild(node); }\nfunction miniTable(key, rows, cols) { const t = byKey[key]; return rows.length ? wrapTable(buildTable(t, rows, cols)) : null; }\n\nfunction showCase(no) {\n  const r = caseRowByNo[no];\n  if (!r) { location.hash = ""; return; }\n  current = null; clear(); setNav("cases");\n  head(L.caseWord + " " + no, get(cases, r, "patient_ref"), [backBtn(), printBtn()]);\n  view.appendChild(kv(cases, r, ["id", "case_number", "files_links"]));\n  const files = cases.ix.files_links !== undefined ? r[cases.ix.files_links] : [];\n  if (files && files.length) {\n    const box = el("div", "card msg");\n    files.forEach((l) => { const a = el("a", "f", l[0]); a.href = l[1]; a.target = "_blank"; a.rel = "noopener"; box.appendChild(a); });\n    section(D.titles.files, box);\n  }\n  const h = miniTable("stage_history", histByCase[no] || [], ["stage", "changed_at", "note"]);\n  if (h) section(D.titles.stage_history, h);\n  const a = miniTable("payment_allocations", allocByCase[no] || [], ["invoice_number", "payment_at", "amount_usd", "amount_local"]);\n  if (a) section(D.titles.payment_allocations, a);\n  const ms = msgsByCase[no] || [];\n  if (ms.length) {\n    const box = el("div", "card");\n    ms.forEach((m) => {\n      const d = el("div", "msg");\n      d.appendChild(el("small", "", get(byKey.messages, m, "sender_name") + " \xb7 " + get(byKey.messages, m, "created_at")));\n      d.appendChild(el("div", "", get(byKey.messages, m, "message")));\n      box.appendChild(d);\n    });\n    section(D.titles.messages, box);\n  }\n}\n\nconst caseCols = ["case_number", "entry_date", "stage", "case_type", "patient_ref", "price_usd", "price_local"];\nfunction showDoctor(id) {\n  const r = doctors.rows.find((x) => get(doctors, x, "id") === id);\n  if (!r) { location.hash = ""; return; }\n  current = null; clear(); setNav("doctors");\n  const name = get(doctors, r, "name"), clinic = get(doctors, r, "clinic");\n  head(name, clinic, [backBtn(), printBtn()]);\n  view.appendChild(kv(doctors, r, ["id", "name"]));\n  const mine = cases.rows.filter((c) => get(cases, c, "doctor") === name && get(cases, c, "clinic") === clinic);\n  const tb = miniTable("cases", mine, caseCols);\n  section(D.titles.cases + " (" + mine.length + ")", tb || el("div", "card empty", D.empty));\n}\nfunction showClinic(id) {\n  const r = clinics.rows.find((x) => get(clinics, x, "id") === id);\n  if (!r) { location.hash = ""; return; }\n  current = null; clear(); setNav("clinics");\n  const name = get(clinics, r, "name");\n  head(name, "", [backBtn(), printBtn()]);\n  view.appendChild(kv(clinics, r, ["id", "name"]));\n  const ds = doctors.rows.filter((d) => get(doctors, d, "clinic") === name);\n  const dt = miniTable("doctors", ds, ["name", "phone", "active"]);\n  if (dt) section(D.titles.doctors + " (" + ds.length + ")", dt);\n  const mine = cases.rows.filter((c) => get(cases, c, "clinic") === name);\n  const tb = miniTable("cases", mine, ["case_number", "entry_date", "doctor", "stage", "case_type", "patient_ref", "price_usd", "price_local"]);\n  section(D.titles.cases + " (" + mine.length + ")", tb || el("div", "card empty", D.empty));\n}\n\nfunction route() {\n  const h = decodeURIComponent(location.hash.slice(1)), p = h.indexOf("/");\n  const kind = p < 0 ? h : h.slice(0, p), arg = p < 0 ? "" : h.slice(p + 1);\n  if (kind === "case") showCase(arg);\n  else if (kind === "doctor") showDoctor(arg);\n  else if (kind === "clinic") showClinic(arg);\n  else if (kind === "t") showTab(arg);\n  else showHome();\n  window.scrollTo(0, 0);\n}\n\n// ---- shell ----\ndocument.title = D.title;\n$("lab").textContent = D.lab;\n$("logo").textContent = Array.from(D.lab.trim())[0] || "?";\n$("date").textContent = D.date;\n(function buildNav() {\n  const nav = $("nav");\n  const add = (key, text, n, hash) => {\n    const b = el("button", "nav"); b.dataset.key = key;\n    b.appendChild(el("span", "", text));\n    if (n !== null) b.appendChild(el("span", "", fmtNum.format(n)));\n    b.onclick = () => { location.hash = hash; };\n    nav.appendChild(b);\n  };\n  add("home", L.home, null, "");\n  let lastGroup = "";\n  tabs.forEach((t) => {\n    if (t.group !== lastGroup) { nav.appendChild(el("div", "grp", L[t.group])); lastGroup = t.group; }\n    add(t.key, t.title, t.rows.length, "t/" + t.key);\n  });\n})();\nwindow.addEventListener("hashchange", route);\nwindow.addEventListener("beforeprint", () => { printing = true; if (current && byKey[current].redraw) byKey[current].redraw(); });\nwindow.addEventListener("afterprint", () => { printing = false; if (current && byKey[current].redraw) byKey[current].redraw(); });\nroute();\n</script>\n</body>\n</html>\n',"__LANG__",a1)
